fn findMax(a: &[i32], n: usize) -> usize {
    // Precondition: 1 <= n <= a.len(), so a[0] is a valid access.
    // Initialize the max index to 0 (the first element of the prefix).
    let mut max_index = 0;

    // Scan through the rest of the prefix, updating max_index when we find a larger value.
    for i in 1..n {
        if a[i] > a[max_index] {
            max_index = i;
        }
    }

    // max_index is guaranteed to be in [0, n) and a[max_index] >= a[i] for all i < n.
    max_index
}

